
/* ================= PLANNER v6 (matches Planner in the repo; Strategy map redesigned) ================= */
const KST={ns:['Not started','#94A3B8'],ot:['On track','#2B63F6'],ar:['At risk','#D97706'],off:['Off track','#DC2626'],hold:['On hold','#64748B'],done:['Completed','#13A592']};
const ob=(n,st,ow,pr,kind,due,kids=[],kpi=[],tasks=[],o={})=>({n,st,ow,pr,kind,due,kids,kpi,tasks,...o});
const PLANS={l2f:{id:'pl1',n:'First 1000 Followers on Facebook',desc:'This is a first step towards our Million Dollar Community.',dates:'2 Nov 2026 to 31 Dec 2026',vision:'A million-dollar community of coaches who build funnels that work.',values:['Results over activity','Human craft'],fa:[
{id:'f1',n:'Social media Posts',c:'#2B63F6',time:'Current',dates:'Nov – Dec',obj:[ob('Write 5 Days Posts','ot','TR',40,'Goal','10 Nov',[ob('Draft day 1–2 posts','done','SN',100,'Sub-objective','5 Nov')],[['Posts published','2 / 5']],['Design post templates'],{overdue:2})]},
{id:'f2',n:'5 Days Post Challenge',c:'#7E5BF2',time:'Upcoming',dates:'Dec',obj:[ob('Launch the challenge page','ns','TR',0,'Goal','1 Dec',[],[['Sign-ups','0 / 300']]),ob('Line up 3 guest coaches','ot','UM',30,'Initiative','20 Nov'),ob('Daily live sessions','ns','TR',0,'Initiative','5 Dec')]},
{id:'f3',n:'Offers',c:'#F07C1A',time:'Upcoming',dates:'Dec',obj:[ob('Package the DFY offer','ns','TR',0,'Goal','15 Dec',[],[['Proposals sent','0 / 10']]),ob('Write the sales page','ns','SN',0,'Initiative','18 Dec'),ob('Price test','ns','TR',0,'Initiative','22 Dec')]}]},
aurj:{id:'pl2',n:'Aurj Launch',desc:'Launch Aurj with a clear offer and daily content.',dates:'1 Nov 2026 to 31 Mar 2027',vision:'Every Urdu-speaking student can learn clearly, in their own language.',values:['Clarity','Respect'],fa:[
{id:'a1',n:'Priority One: Foundations',c:'#0EA5A4',time:'Current',dates:'Nov',obj:[ob('Write: Vision Mission statement.','done','TR',100,'Goal','5 Nov'),ob('Create Student Avatar','ot','TR',50,'Goal','20 Nov'),ob('Create Dream 100 List.','ns','UM',0,'Goal','30 Nov')]},
{id:'a2',n:'Priority Two: Offers',c:'#F07C1A',time:'Current',dates:'Nov – Dec',obj:[ob('Create: 4 Core Offers','ot','TR',25,'Goal','15 Dec',[],[],['Build 4 Products']),ob('Research Avatar’s Needs and Problems','ns','SN',0,'Goal','30 Nov')]},
{id:'a3',n:'Priority Three: Social Media Reels and Posts',c:'#7E5BF2',time:'Upcoming',dates:'Dec',obj:[ob('Create Your First Show','ns','TR',0,'Goal','10 Dec'),ob('Create 10 Days Posts Challenge.','ns','SN',0,'Goal','15 Dec'),ob('Create 10 Days Reels Challenge','ns','AR',0,'Goal','20 Dec')]},
{id:'a4',n:'Priority Four',c:'#64748B',time:'Upcoming',dates:'Jan',obj:[ob('Map What funnels to Create','ns','TR',0,'Goal','5 Jan'),ob('Write their Copy','ns','SN',0,'Goal','12 Jan'),ob('Design and Build the Funnels','ns','BK',0,'Goal','25 Jan')]}]}};
const PLN=()=>PLANS[org()];const pobjs=()=>PLN().fa.flatMap(f=>f.obj.map((o,i)=>Object.assign(o,{fa:f,oid:f.id+'-'+i})));
const PS={sel:null,sb:'builder',view:'list',zoom:1,collapsed:new Set(),focus:null,dtab:'overview',myl:'list',rtab:'summary',mtab:'map',strat:0};
const PLNAV6=[['planner/home','Home','home'],['planner/mywork','My work','mywork',null,null,'My work'],['planner/plans','Plans','planner'],['planner/alignment','Alignment','layers'],['planner/reports','Reports','chart'],['planner/model','Strategy model','key',null,null,'Model']];
const kst=s=>`<span class="kst" style="--c:${KST[s][1]}"><i></i>${KST[s][0]}</span>`;
function plTop(title){return `<div class="pltop"><h1 class="t1">${title}</h1><span class="grow"></span><label class="inp sm" style="width:min(260px,40vw)">${ic('search',14)}<input placeholder="Search objectives  ( / )" data-filter></label><button class="btn primary sm" data-act="plcreate">Create${ic('down',13)}</button><button class="btn ghost sm needs" data-act="plneeds">Needs you <span class="nb">1</span>${ic('down',13)}</button></div>`}
const plShell=(cur,body,crumbs,o={})=>shell('planner',{nav:PLNAV6,cur,body,crumbs:crumbs||[['Planner']],...o});
const planBar=()=>{const P=PLN();const v=Math.round(pobjs().reduce((s,o)=>s+o.pr,0)/pobjs().length);return `<div class="planbar6"><button class="plsel" data-act="toast:Switch plan: every plan in ${oname()}.">${P.n}${ic('down',14)}</button><button class="iconbtn sm" aria-label="Favourite">${ic('star',16)}</button><span class="prog thin" style="--v:${v}%;width:140px"><i></i></span><b class="mono">${v}%</b>${org()==='l2f'?'<span class="pill warn" style="height:22px">Review overdue</span>':''}</div>`};
VIEWS.planner=p=>{const pg=p[0]||'home';const P=PLN();const O=pobjs();
if(pg==='plan')return planPage(p[1]||'map');
if(pg==='home'){const cnt=k=>O.filter(o=>o.st===k).length;const v=Math.round(O.reduce((s,o)=>s+o.pr,0)/O.length);const steps=[['Write your vision','One or two sentences on what success looks like.',1],['Add your values','The principles that guide decisions.',0],['Set up focus areas','The few themes your goals are grouped under.',1],['Add your first goals','Objectives, results and initiatives that make the vision real.',1],['Schedule a review','A date to check progress together.',0]];
return plShell('planner/home',`${plTop('Home')}${planBar()}
<section class="plhero"><div><h2>${P.n}</h2><p>${P.desc}</p><small>${P.dates}</small></div><div class="ringw"><span class="ring lg" style="--v:${v}"><b>${v}%</b></span><small>Overall progress</small></div></section>
<h3 class="h6">Plan health</h3><div class="kpirow">${kpiT(O.length,'Objectives')}${kpiT(cnt('ot'),'▲ On track')}${kpiT(cnt('ar'),'◆ At risk')}${kpiT(cnt('off'),'▼ Off track')}${kpiT(O.filter(o=>o.overdue).length,'Overdue',null,'bad')}${kpiT(0,'Without owner')}</div>
<div class="distbar">${Object.keys(KST).map(k=>`<i style="--v:${cnt(k)/O.length*100}%;--c:${KST[k][1]}" title="${KST[k][0]}"></i>`).join('')}</div><div class="legend" style="margin:8px 0 18px">${Object.keys(KST).map(k=>`<span><i style="--c:${KST[k][1]}"></i>${KST[k][0]} <b>${cnt(k)}</b></span>`).join('')}</div>
<section class="card6"><header><h2>Getting started</h2><span class="muted">${steps.filter(s=>s[2]).length} of 5 done</span></header>${steps.map(([t,s,d])=>`<div class="gs ${d?'done':''}">${d?ic('check',16,'',2.6):'<i class="gs-c"></i>'}<span><b>${t}</b> ${s}</span>${d?'':`<button class="btn ghost sm" data-act="${t.includes('review')?'nav:planner/plan/reviews':'nav:planner/plan/settings'}">Go</button>`}</div>`).join('')}</section>
<div class="grid-h" style="margin-top:16px"><div class="stackcol"><section class="card6"><header><h2>Needs attention</h2></header>${O.filter(o=>o.overdue||o.st==='ar').map(o=>`<button class="attn" data-act="pobj:${o.oid}"><b>${o.n}</b><span>${PEOPLE[o.ow][0]}</span><span class="pill danger" style="height:22px">Overdue by ${o.overdue||1} days</span></button>`).join('')||'<p class="hint pad-s">Nothing needs attention.</p>'}</section>
<section class="card6"><header><h2>Focus areas</h2></header>${P.fa.map(f=>{const v=Math.round(f.obj.reduce((s,o)=>s+o.pr,0)/f.obj.length);return `<a class="farow" href="#/planner/plan/map" style="--c:${f.c}"><span class="fa-edge"></span><span class="grow"><b>${f.n}</b><small>${f.obj.length} goals · ${f.time}</small><span class="distbar sm">${Object.keys(KST).map(k=>`<i style="--v:${f.obj.filter(o=>o.st===k).length/f.obj.length*100}%;--c:${KST[k][1]}"></i>`).join('')}</span></span><b class="mono">${v}%</b></a>`}).join('')}</section></div>
<div class="stackcol"><section class="card6"><header><h2>Reviews</h2></header><p class="tx2 pad-s">No review is scheduled.</p><a class="btn ghost sm full" href="#/planner/plan/reviews" style="margin:0 16px 14px;width:calc(100% - 32px)">Open reviews</a></section><section class="card6"><header><h2>My work</h2></header><div class="kpirow two pad-s">${kpiT(O.filter(o=>o.ow==='TR').length,'My objectives')}${kpiT(0,'Open actions')}</div><p class="hint pad-s">Across all plans in ${oname()}.</p><a class="btn ghost sm" href="#/planner/mywork" style="margin:0 16px 14px">Go to my objectives</a></section></div></div>`,[['Planner'],['Home']])}
if(pg==='mywork')return plShell('planner/mywork',`${plTop('My work')}<div class="tb6">${vsw([['list','List','list'],['board','Board','board']],PS.myl,'plmyl')}<span class="grow"></span><button class="chip sm" aria-pressed="false" data-act="chipt">Overdue</button><button class="chip sm" aria-pressed="false" data-act="chipt">Due this week</button></div>
<section class="card6"><header><h2>My objectives</h2><span class="muted">Grouped by status</span></header>${['ot','ns','done'].map(s=>{const L=O.filter(o=>o.ow==='TR'&&o.st===s);return L.length?`<div class="sect-h">${kst(s)}<span class="cnt">${L.length}</span></div>${L.map(o=>`<button class="objrow" data-act="pobj:${o.oid}"><span class="ring xs" style="--v:${o.pr};--rc:${o.fa.c}"></span><b>${o.n}</b><span class="tx2">${o.fa.n}</span><span class="muted">${o.due}</span><span class="btn ghost sm">Post update</span></button>`).join('')}`:''}).join('')}</section>
<section class="card6" style="margin-top:14px"><header><h2>My actions</h2></header><div class="kanban k6 tight">${['To do','In progress','On hold','Done'].map((c,i)=>`<div class="kcol"><div class="kcol-h"><b>${c}</b><span class="cnt">${[1,0,0,1][i]}</span></div>${i===0?'<div class="kcard k6c"><b>Design post templates</b><span class="foot">Write 5 Days Posts · 10 Nov</span></div>':i===3?'<div class="kcard k6c done"><b>Draft day 1–2 posts</b></div>':''}</div>`).join('')}</div></section>`,[['Planner'],['My work']]);
if(pg==='plans')return plShell('planner/plans',`${plTop('Plans')}<div class="tb6"><label class="inp sm">${ic('search',14)}<input placeholder="Search plans" data-filter></label><label class="chk"><input type="checkbox"> Show archived</label><span class="grow"></span><button class="btn primary sm" data-act="plnewplan">${ic('plus',15,'',2.2)}New plan</button></div><div class="tbl6"><div class="thd"><span>Plan</span><span>Progress</span><span>Focus areas</span><span>Owner</span><span>Next review</span><span></span></div>${[[PLN().n,Math.round(O.reduce((s,o)=>s+o.pr,0)/O.length),PLN().fa.length,'TR','Not scheduled',1],['Q1 2027 Delivery',0,2,'BK','15 Jan',0]].map(([n,v,f,k,r,fav])=>`<a class="tr" href="#/planner/plan/map" data-row="${n}"><span class="t1c">${ic('star',15)}<b>${n}</b></span><span class="pgc"><span class="prog thin" style="--v:${v}%"><i></i></span>${v}%</span><span>${f}</span><span>${av(k,24)}</span><span>${r}</span><span></span></a>`).join('')}</div>`,[['Planner'],['Plans']]);
if(pg==='alignment')return plShell('planner/alignment',`${plTop('Alignment')}<div class="tb6">${vsw([['plans','Plans'],['objectives','Objectives']],'plans','noop')}<span class="grow"></span><button class="iconbtn sm" aria-label="Zoom out">${ic('zout',16)}</button><button class="iconbtn sm" aria-label="Zoom in">${ic('zin',16)}</button></div><div class="aln"><div class="al-col"><div class="al-b">${ic('compass',16)}<b>${oname()} vision</b></div></div><div class="al-col">${[PLN().n,'Q1 2027 Delivery'].map((n,i)=>`<a class="al-b" href="#/planner/plan/map"><b>${n}</b><span class="prog thin" style="--v:${[12,0][i]}%"><i></i></span><small>${[PLN().fa.length,2][i]} focus areas</small></a>`).join('')}</div><div class="al-col">${PLN().fa.slice(0,3).map(f=>`<div class="al-b" style="border-left:3px solid ${f.c}"><b>${f.n}</b><small>${f.obj.length} objectives</small></div>`).join('')}</div></div>`,[['Planner'],['Alignment']]);
if(pg==='reports')return plShell('planner/reports',`${plTop('Reports')}${planBar()}<div class="tabs6">${[['summary','Summary'],['all','All objectives'],['metrics','Metrics']].map(([k,l])=>`<button aria-selected="${PS.rtab===k}" data-act="plrt:${k}">${l}</button>`).join('')}</div>
${PS.rtab==='summary'?`<div class="grid-h"><section class="card6"><header><h2>By focus area</h2><button class="lk" data-act="toast:Exports CSV.">Export</button></header>${PLN().fa.map(f=>`<div class="hbar"><span><i class="dotc" style="--c:${f.c};display:inline-block"></i> ${f.n}</span><span class="prog" style="--v:${Math.round(f.obj.reduce((s,o)=>s+o.pr,0)/f.obj.length)}%"><i style="background:${f.c}"></i></span><b>${f.obj.length}</b></div>`).join('')}</section><section class="card6"><header><h2>By owner</h2></header>${[...new Set(O.map(o=>o.ow))].map(k=>`<div class="hbar"><span>${av(k,20)} ${PEOPLE[k][0]}</span><span class="prog" style="--v:${O.filter(o=>o.ow===k).length/O.length*100}%"><i></i></span><b>${O.filter(o=>o.ow===k).length}</b></div>`).join('')}</section><section class="card6"><header><h2>Risks · overdue · stale</h2></header>${O.filter(o=>o.overdue).map(o=>`<div class="attn"><b>${o.n}</b><span class="pill danger" style="height:22px">Overdue</span></div>`).join('')}<div class="attn"><b>Create Student Avatar</b><span class="pill warn" style="height:22px">No update in 14 days</span></div></section></div>`:''}
${PS.rtab==='all'?`<div class="tb6"><label class="inp sm">${ic('search',14)}<input placeholder="Filter" data-filter></label><span class="grow"></span><button class="btn ghost sm" data-act="toast:Import objectives from a CSV file.">${ic('upload',15)}Import CSV</button><button class="btn ghost sm" data-act="toast:Exports CSV.">${ic('download',15)}Export CSV</button></div><div class="tbl6"><div class="thd"><span>Title</span><span>Focus area</span><span>Owner</span><span>Status</span><span>Progress</span><span>Due</span></div>${O.map(o=>`<button class="tr" data-act="pobj:${o.oid}" data-row="${o.n}"><span class="t1c"><input type="checkbox" aria-label="Select" onclick="event.stopPropagation()"><b>${o.n}</b></span><span>${o.fa.n}</span><span>${av(o.ow,22)}</span><span>${kst(o.st)}</span><span>${o.pr}%</span><span>${o.due}</span></button>`).join('')}</div>`:''}
${PS.rtab==='metrics'?`<div class="tbl6"><div class="thd"><span>KPI</span><span>Objective</span><span>Latest</span><span>Target</span><span>Trend</span><span></span></div>${O.flatMap(o=>o.kpi.map(k=>`<div class="tr"><span class="t1c"><b>${k[0]}</b></span><span>${o.n}</span><span class="mono">${k[1].split(' / ')[0]}</span><span class="mono">${k[1].split(' / ')[1]||'—'}</span><span><svg viewBox="0 0 80 20" class="spk"><polyline points="0,18 20,14 40,12 60,8 80,6"/></svg></span><span><button class="btn ghost sm" data-act="plreading">Record reading</button></span></div>`)).join('')}</div>`:''}`,[['Planner'],['Reports']]);
if(pg==='model')return strategyModel(p[1]||PS.mtab);
return plShell('planner/home','')};
function planPage(tab){const P=PLN();const T=[['map','Planner'],['timeline','Timeline'],['reviews','Reviews'],['settings','Settings']];let body='';
if(tab==='map')body=`<div class="tb6"><button class="btn ghost sm" data-act="plfa">${ic('plus',15)}Add focus area</button>${vsw([['list','List','list'],['board','Board','board']],PS.view,'plview')}<button class="btn primary sm" data-act="plobjnew">${ic('plus',15,'',2.2)}Add objective</button><span class="grow"></span><label class="inp sm">${ic('search',14)}<input placeholder="Find objectives" data-filter></label><button class="fdd">${ic('filter',13)}Filters</button><button class="fdd">${ic('sliders',13)}Display</button><button class="fdd">${ic('star',13)}Saved views</button><button class="fdd" data-act="chipt" aria-pressed="false">Hide completed</button></div>
${PS.view==='list'?P.fa.map(f=>{const v=Math.round(f.obj.reduce((s,o)=>s+o.pr,0)/f.obj.length);return `<section class="band" style="--c:${f.c}"><div class="band-h"><span class="band-e"></span><h2>${f.n}</h2><span class="tchip">${f.time}</span><small>${f.dates} · ${f.obj.length} objectives · avg ${v}%</small><span class="grow"></span><button class="btn quiet sm" data-act="plobjnew">${ic('plus',14)}Add objective</button><button class="btn quiet sm" data-act="pltw">Turn into work</button><button class="btn quiet sm" data-act="plfa">Edit</button></div><div class="objhd"><span>Objective</span><span>Kind</span><span>Owner</span><span>Status</span><span>Progress</span><span>Due</span><span></span></div>${f.obj.map(o=>objRow(o,0)+o.kids.map(k=>objRow(Object.assign(k,{fa:f,oid:o.oid}),1)).join('')).join('')}</section>`}).join('')+`<button class="addband" data-act="plfa">${ic('plus',16)}Add focus area</button>`:`<div class="kanban k6">${P.fa.map(f=>`<div class="kcol" style="border-top:3px solid ${f.c}"><div class="kcol-h"><b>${f.n}</b><span class="cnt">${f.obj.length}</span></div>${f.obj.map(o=>`<button class="kcard k6c" data-act="pobj:${o.oid}"><b>${o.n}</b><span class="foot">${av(o.ow,20)}${kst(o.st)}<span class="mono" style="margin-left:auto">${o.pr}%</span></span></button>`).join('')}</div>`).join('')}</div>`}`;
if(tab==='timeline')body=`<div class="gantt g6"><div class="gantt-in"><div class="g-head"><span class="over" style="padding:10px 14px">Objective</span><div class="wk">${['Nov','Dec','Jan','Feb','Mar','Apr'].map(m=>`<span>${m}</span>`).join('')}</div></div>${P.fa.map(f=>`<div class="g-sec" style="color:${f.c}">${f.n}</div>${f.obj.map((o,i)=>`<div class="g-row"><span class="gn">${o.n}</span><div class="g-track"><button class="g-bar" style="left:${i*8}%;width:${18+i*6}%;--c:${f.c}" data-act="pobj:${o.oid}">${o.pr}%</button></div></div>`).join('')}`).join('')}</div></div>`;
if(tab==='reviews')body=`<div class="tb6"><span class="grow tx2">Holding a review freezes a snapshot of every objective, so you can compare.</span><button class="btn primary sm" data-act="toast:Review scheduled.:ok">${ic('cal',15)}Schedule a review</button></div><div class="grid-h"><section class="card6"><header><h2>Scheduled</h2></header><p class="hint pad-s">No review is scheduled.</p></section><section class="card6"><header><h2>Held</h2></header><p class="hint pad-s">Held reviews with their snapshot appear here.</p></section></div>`;
if(tab==='settings')body=`<div class="setgrid"><section class="card6"><header><h2>Plan details</h2><button class="lk" data-act="plnewplan">Edit plan details</button></header><dl class="kv2 pad-s"><dt>Name</dt><dd>${P.n}</dd><dt>Description</dt><dd>${P.desc}</dd><dt>Period</dt><dd>${P.dates}</dd></dl></section><section class="card6"><header><h2>Vision</h2></header><div class="pad-s"><textarea class="ta6">${P.vision}</textarea><button class="btn primary sm" data-act="toast:Vision saved.:ok">Save vision</button></div></section><section class="card6"><header><h2>Values</h2></header><div class="pad-s">${P.values.map(v=>`<div class="mrow"><b>${v}</b><button class="iconbtn xs" aria-label="Delete value">${ic('trash',13)}</button></div>`).join('')}<div class="inp sm" style="margin-top:8px"><input placeholder="New value"></div></div></section><section class="card6"><header><h2>Focus areas</h2><button class="lk" data-act="plfa">Add focus area</button></header>${P.fa.map(f=>`<div class="mrow pad-s"><i class="dotc" style="--c:${f.c}"></i><b>${f.n}</b><span class="grow"></span><button class="lk" data-act="plfa">Edit</button><button class="lk">Archive</button></div>`).join('')}</section><section class="card6"><header><h2>Review rhythm</h2></header><div class="pad-s"><div class="field"><label>Review every</label><select><option>Month</option><option>Quarter</option></select></div><button class="btn ghost sm">Save rhythm</button></div></section><section class="card6"><header><h2>Archive</h2></header><p class="hint pad-s">Archived plans are read-only and hidden from the plan switcher.</p><button class="btn ghost sm" style="margin:0 16px 14px">Archive this plan</button></section></div>`;
return plShell('planner/plans',`${plTop(P.n)}${planBar()}<div class="tabs6 big">${T.map(([k,l])=>`<a href="#/planner/plan/${k}" aria-selected="${k===tab}">${l}</a>`).join('')}</div>${body}`,[['Planner','planner/plans'],[P.n]])}
const objRow=(o,sub)=>`<div class="objr ${sub?'sub':''}" data-ctx="pobjc:${o.oid}"><button class="on" data-act="pobj:${o.oid}">${sub?'<span class="sublink"></span>':''}${o.n}</button><span class="kchip">${o.kind}</span><span>${av(o.ow,22)}</span><span>${kst(o.st)}</span><span class="pace"><span class="prog thin" style="--v:${o.pr}%"><i style="background:${o.fa.c}"></i></span><i class="pm" style="left:35%" title="Expected pace"></i><b class="mono">${o.pr}%</b></span><span class="${o.overdue?'od':''}">${o.due}</span><span class="oa"><button class="iconbtn xs" aria-label="Add sub-objective" data-act="toast:Add a sub-objective.">${ic('plus',14)}</button><button class="iconbtn xs" aria-label="More" data-act="toast:Edit · Move · Archive">${ic('more',14)}</button></span></div>`;
/* ---------- Objective drawer: Overview · Updates · KPIs · Tasks · Risks · Comments · History ---------- */
function objDrawer(oid){const o=pobjs().find(x=>x.oid===oid)||pobjs()[0];const t=PS.dtab;const T=[['overview','Overview'],['updates','Updates'],['kpis','KPIs',o.kpi.length],['tasks','Tasks',o.tasks.length],['risks','Risks'],['comments','Comments'],['history','History']];let b='';
if(t==='overview')b=`<div class="ov-prog"><span class="ring lg" style="--v:${o.pr};--rc:${o.fa.c}"><b>${o.pr}%</b></span><div><b>Progress</b><p class="hint">From ${o.kpi.length?'its KPIs':'manual updates'} · expected 35% by today</p></div></div><div class="tfields">${[['Kind',`<span class="kchip">${o.kind}</span>`],['Status',kst(o.st)],['Priority','Normal'],['Weight','1'],['Start date','2 Nov'],['Due date',`<span class="${o.overdue?'od':''}">${o.due}</span>`],['Update schedule','Weekly · next Mon'],['Tags','—'],['Linked project',`<a href="#/projects/p/p1/overview">Harry Kaye quiz funnel</a>`],['Linked value',PLN().values[0]]].map(([l,v])=>`<div class="tf"><span class="tf-l">${l}</span><span class="tf-v">${v}</span></div>`).join('')}</div><section class="tps"><h3>Description</h3><p class="tx2">No description yet.</p></section><section class="tps"><h3>Latest update</h3><p class="tx2">No updates posted yet.</p></section><section class="tps"><h3>Sub-objectives</h3>${o.kids.map(k=>`<div class="mrow">${kst(k.st)}<b>${k.n}</b></div>`).join('')||'<p class="hint">No sub-goals. Use the Actions menu to add one.</p>'}</section>`;
if(t==='updates')b=`<div class="upd-new"><div class="row2"><div class="field"><label>Status</label><select><option>On track</option><option>At risk</option><option>Off track</option></select></div><div class="field"><label>Progress</label><input value="${o.pr}%"></div></div><div class="field"><label>What changed?</label><textarea rows="3"></textarea></div><button class="btn primary sm" data-act="toast:Update posted.:ok">Post update</button></div><p class="hint" style="margin-top:12px">No updates posted yet.</p>`;
if(t==='kpis')b=`${o.kpi.map(k=>`<div class="kpicard"><b>${k[0]}</b><span class="mono big">${k[1]}</span><span class="prog thin" style="--v:40%"><i style="background:${o.fa.c}"></i></span><small class="muted">Higher is better · start 0</small><button class="btn ghost sm" data-act="plreading">Record reading</button></div>`).join('')||'<p class="hint">No KPIs yet.</p>'}<button class="addrow" data-act="plkpi">${ic('plus',14)}Add KPI (start from a saved KPI type)</button>`;
if(t==='tasks')b=`${o.tasks.map(n=>`<div class="mrow"><button class="done6">${ic('check',11,'',3)}</button><b>${n}</b><span class="grow"></span>${av(o.ow,20)}</div>`).join('')||'<p class="hint">No tasks yet.</p>'}<button class="addrow" data-act="toast:Task added.">${ic('plus',14)}Add task</button><button class="btn ghost sm" data-act="pltw">Turn into work</button>`;
if(t==='risks')b=`<button class="addrow" data-act="toast:Risk added.">${ic('plus',14)}Add risk: what could go wrong, how likely, impact, and the plan</button>`;
if(t==='comments')b=`<p class="hint">No comments yet.</p><div class="composer"><textarea placeholder="Comment or @mention"></textarea></div>`;
if(t==='history')b=`<p class="hint">${PEOPLE[o.ow][0]} created this objective · 2 Nov<br>Status changed to ${KST[o.st][0]} · 6 Nov</p>`;
openDrawer(`<div class="tp-head"><span class="kchip">${o.kind}</span><span class="grow"></span><button class="iconbtn sm" aria-label="Previous">${ic('right',16).replace('<svg','<svg style="transform:scaleX(-1)"')}</button><button class="iconbtn sm" aria-label="Next">${ic('right',16)}</button><button class="iconbtn sm" aria-label="Copy link" data-act="toast:Link copied.:ok">${ic('link',16)}</button><button class="btn quiet sm" data-act="toast:Add sub-objective · KPI · task · Archive · Delete permanently">Actions${ic('down',12)}</button><button class="iconbtn sm" data-act="drawerx" aria-label="Close">${ic('x',17)}</button></div><div class="tp-body"><nav class="tp-crumb"><span class="pdot" style="--c:${o.fa.c}"></span>${PLN().n}<span>›</span>${o.fa.n}</nav><textarea class="tp-title" rows="2">${esc(o.n)}</textarea><div class="ohead">${kst(o.st)}<span class="achip">${av(o.ow,20)}${PEOPLE[o.ow][0]}</span><span class="pill">Normal priority</span></div><div class="tabs6 sm" role="tablist">${T.map(([k,l,n])=>`<button aria-selected="${t===k}" data-act="pdtab:${k}|${oid}">${l}${n?` <span class="cnt">${n}</span>`:''}</button>`).join('')}</div><div class="dtab">${b}</div></div>`,'task6')}
/* ---------- Strategy model with the redesigned Strategy map ---------- */
function strategyModel(tab){const P=PLN();const T=[['map','Strategy map'],['kinds','Objective kinds'],['kpi','KPI types'],['fa','Focus areas'],['horizons','Time horizons'],['tpl','Templates']];let body='';
if(tab==='map'){const S=[[P.n,1],[org()==='aurj'?'Aurj Academy':'Funnel Done Right Challenge',0],[org()==='aurj'?'3 pieces of content daily.':'Q1 Delivery',0]];const stats=`${P.fa.length} focus areas · ${pobjs().length} objectives · ${pobjs().reduce((s,o)=>s+o.kpi.length,0)} KPIs · ${pobjs().reduce((s,o)=>s+o.tasks.length,0)} tasks · used by 1 plan`;
body=`<div class="smhead"><div><h2 class="t1">Strategy map</h2><p class="tx2">Create a strategy and draw it: focus areas, their objectives, and the sub-objectives, KPIs and tasks under each. Then create plans from it with everything already in place.</p></div><button class="btn primary sm" data-act="plnewstrat">${ic('plus',15,'',2.2)}New strategy</button></div>
<div class="stratchips">${S.map(([n,c],i)=>`<button aria-pressed="${PS.strat===i}" data-act="plstrat:${i}">${n} <span>· ${c} plan${c===1?'':'s'}</span></button>`).join('')}</div>
<div class="smbar"><div><b>${P.n}</b><small>${stats}</small></div><span class="grow"></span>${vsw([['builder','Builder','map'],['grid','Grid','tiles']],PS.sb,'plsb')}<button class="btn primary sm" data-act="toast:Creates a plan with these focus areas, objectives, KPIs and tasks.:ok">Create a plan from it</button><button class="btn ghost sm" data-act="toast:Rename · Duplicate · Delete strategy">More${ic('down',12)}</button></div>
${PS.sb==='builder'?builder(P):gridMap(P)}`}
if(tab==='kinds')body=`<div class="split"><section class="card6"><header><h2>Kinds of objective</h2><button class="lk" data-act="toast:New kind.">${ic('plus',13)}Add</button></header>${[['Goal',9,'#2B63F6'],['Initiative',3,'#F07C1A'],['Sub-objective',1,'#7E5BF2']].map(([n,c,col])=>`<div class="mrow pad-s"><i class="dotc" style="--c:${col}"></i><b>${n}</b><span class="cnt">${c}</span><span class="grow"></span><button class="lk">Edit</button></div>`).join('')}</section><section class="card6"><header><h2>What can sit under what</h2></header><div class="nest pad-s">${['Plan','Focus area','Goal','Initiative · Sub-objective'].map((n,i)=>`<div class="nest-n" style="--i:${i}">${n}</div>`).join('<span class="nest-a">↓</span>')}<p class="hint">Sub-objective can hold itself (loops are marked ↺).</p></div></section></div>`;
if(tab==='kpi')body=`<div class="tb6"><span class="grow tx2">Reusable KPI types appear when you add a KPI to an objective.</span><button class="btn primary sm" data-act="toast:New KPI type.">${ic('plus',15,'',2.2)}New KPI type</button></div><div class="tbl6"><div class="thd"><span>KPI type</span><span>Unit</span><span>A good result goes</span><span>Available on</span><span></span><span></span></div>${[['Followers','people','Up','Goal'],['Sign-ups','people','Up','Any kind'],['Cost per lead','$','Down','Initiative']].map(([n,u,d,k])=>`<div class="tr"><span class="t1c"><b>${n}</b></span><span>${u}</span><span>${d}</span><span>${k}</span><span></span><span><button class="lk">Edit</button></span></div>`).join('')}</div>`;
if(tab==='fa')body=`<div class="tb6"><span class="grow tx2">Reusable focus areas you can pick when you add one to a plan.</span><button class="btn primary sm">${ic('plus',15,'',2.2)}New reusable focus area</button></div><div class="cardgrid">${P.fa.map(f=>`<div class="card6 pad-s" style="border-top:3px solid ${f.c}"><b>${f.n}</b><p class="hint">Used in 1 plan</p></div>`).join('')}</div>`;
if(tab==='horizons')body=`<div class="tbl6"><div class="thd"><span>Name</span><span>From</span><span>To</span><span></span><span></span><span></span></div>${[['Q4 2026','1 Oct','31 Dec'],['2027','1 Jan','31 Dec']].map(([n,a,b])=>`<div class="tr"><span class="t1c"><b>${n}</b></span><span>${a}</span><span>${b}</span><span></span><span></span><span><button class="lk">Edit</button></span></div>`).join('')}</div>`;
if(tab==='tpl')body=`<div class="cardgrid">${['Launch plan','Quarterly growth','Content engine'].map(n=>`<div class="card6 pad-s"><b>${n}</b><p class="hint">3 focus areas · 8 objectives</p><button class="btn ghost sm">Create plan</button></div>`).join('')}</div>`;
return plShell('planner/model',`${plTop('Strategy model')}<div class="tabs6 big">${T.map(([k,l])=>`<a href="#/planner/model/${k}" aria-selected="${k===tab}">${l}</a>`).join('')}</div>${body}`,[['Planner'],['Strategy model']],{wide:true})}
function builder(P){const node=(o,f,lvl)=>`<div class="sn ${lvl?'kid':''} ${PS.sel===o.oid+lvl?'sel':''}" style="--c:${f.c}" data-act="snsel:${o.oid}|${lvl}" data-ctx="pobjc:${o.oid}" tabindex="0"><div class="sn-t"><span class="sn-k">${o.kind}</span><b>${o.n}</b><button class="iconbtn xs sn-m" aria-label="More">${ic('more',13)}</button></div><div class="sn-meta">${av(o.ow,18)}${kst(o.st)}${o.kpi.length?`<span class="sn-c">${ic('chart',11)}${o.kpi.length}</span>`:''}${o.tasks.length?`<span class="sn-c">${ic('check',11)}${o.tasks.length}</span>`:''}</div><div class="sn-add"><button data-act="toast:Add a KPI: pick a saved KPI type or create one.">+ KPI</button><button data-act="toast:Add a task.">+ Task</button><button data-act="toast:Add a sub-objective.">+ Sub</button></div></div>`;
const leaf=(o,f)=>[...o.kids.map(k=>`<div class="sleaf" style="--c:${f.c}">${ic('target',12)}${k.n}</div>`),...o.kpi.map(k=>`<div class="sleaf kpi" style="--c:${f.c}">${ic('chart',12)}${k[0]}<b class="mono">${k[1]}</b></div>`),...o.tasks.map(t=>`<div class="sleaf task" style="--c:${f.c}">${ic('check',12)}${t}</div>`)].join('');
return `<div class="sbw"><div class="sbc" id="sbc"><div class="sbtools"><label class="inp sm">${ic('search',14)}<input placeholder="Find on the map" data-filter></label><span class="vs"></span><button class="iconbtn sm" data-act="sbz:-1" aria-label="Zoom out">${ic('zout',16)}</button><b class="mono" id="sbzl">${Math.round(PS.zoom*100)}%</b><button class="iconbtn sm" data-act="sbz:1" aria-label="Zoom in">${ic('zin',16)}</button><button class="iconbtn sm" data-act="sbz:0" aria-label="Fit">${ic('target',16)}</button><span class="vs"></span><button class="chip sm" data-act="sbcollapse">${PS.collapsed.size?'Expand all':'Collapse all'}</button><span class="sblegend"><i class="lg-f"></i>Focus area<i class="lg-o"></i>Objective<i class="lg-l"></i>KPI · task · sub</span></div>
<div class="sbworld" style="transform:scale(${PS.zoom})"><div class="sroot">${ic('layers',16)}<b>${P.n}</b><small>${P.fa.length} focus areas</small></div><div class="slanes">${P.fa.map(f=>`<div class="slane ${PS.focus&&PS.focus!==f.id?'dim':''}" style="--c:${f.c}" data-ctx="sfa:${f.id}"><div class="sfa"><div class="sn-t"><b>${f.n}</b><button class="iconbtn xs" aria-label="Focus on this area" title="Focus" data-act="sbfocus:${f.id}">${ic('eye2',13)}</button><button class="iconbtn xs" aria-label="${PS.collapsed.has(f.id)?'Expand':'Collapse'}" data-act="sbcol:${f.id}">${ic(PS.collapsed.has(f.id)?'plus':'down',13)}</button></div><small>${f.obj.length} objectives · ${f.time}</small><button class="sfa-add" data-act="toast:Add an objective under ${f.n}.">+ Objective</button></div>${PS.collapsed.has(f.id)?`<div class="scollapsed">${f.obj.length} objectives hidden</div>`:`<div class="sobjs">${f.obj.map(o=>`<div class="sbranch">${node(o,f,0)}${o.kids.length+o.kpi.length+o.tasks.length?`<div class="sleaves">${leaf(o,f)}</div>`:''}</div>`).join('')}</div>`}</div>`).join('')}<button class="saddfa" data-act="plfa">${ic('plus',16)}Focus area</button></div></div>
<div class="sbmini" aria-hidden="true">${P.fa.map(f=>`<i style="--c:${f.c};height:${10+f.obj.length*6}px"></i>`).join('')}<span class="vp"></span></div></div>
<aside class="sbinsp">${PS.sel?(()=>{const o=pobjs().find(x=>x.oid===PS.sel.slice(0,-1))||pobjs()[0];return `<p class="over" style="color:${o.fa.c}">${o.fa.n}</p><input class="tp-title sm" value="${esc(o.n)}"><div class="field"><label>Kind</label><select><option>${o.kind}</option><option>Goal</option><option>Initiative</option></select></div><div class="field"><label>Owner when a plan is created</label><select><option>${PEOPLE[o.ow][0]}</option></select></div><p class="sec-t">KPIs</p>${o.kpi.map(k=>`<div class="mrow"><b>${k[0]}</b><span class="mono">${k[1].split(' / ')[1]||''}</span></div>`).join('')||'<p class="hint">None.</p>'}<button class="addrow">${ic('plus',14)}KPI</button><p class="sec-t">Tasks</p>${o.tasks.map(t=>`<div class="mrow">${ic('check',13)}${t}</div>`).join('')||'<p class="hint">None.</p>'}<button class="addrow">${ic('plus',14)}Task</button><div style="display:flex;gap:8px;margin-top:12px"><button class="btn ghost sm">Move to…</button><button class="btn quiet sm danger-t">Remove from strategy</button></div>`})():`<p class="over">Inspector</p><p class="tx2" style="margin-top:6px">Select any box to edit it here. Use the <b>+</b> buttons on a box to grow the map.</p><div class="kh"><p class="sec-t">Keyboard</p>${[['Tab','Add a child'],['Enter','Add a sibling'],['Arrows','Move between boxes'],['F2','Rename'],['Delete','Remove']].map(([k,d])=>`<div class="krow"><kbd>${k}</kbd><span>${d}</span></div>`).join('')}</div>`}</aside></div>`}
function gridMap(P){return `<div class="sgrid">${P.fa.map(f=>`<div class="sgc" style="--c:${f.c}"><div class="sfa"><b>${f.n}</b><small>${f.obj.length} objectives</small></div>${f.obj.map(o=>`<div class="sn" style="--c:${f.c}"><div class="sn-t"><b>${o.n}</b></div><div class="sn-meta">${o.kpi.map(k=>`<span class="sn-c">${ic('chart',11)}${k[0]}</span>`).join('')}${o.tasks.map(t=>`<span class="sn-c">${ic('check',11)}${t}</span>`).join('')}</div></div>`).join('')}<button class="sfa-add">+ Objective</button></div>`).join('')}</div><p class="hint" style="margin-top:8px">Grid: each column is a focus area with its objectives, KPIs, tasks and sub-objectives. Builder: the same strategy as a map, read left to right.</p>`}
CTX.pobjc=v=>[['edit','Open','pobj:'+v],['plus','Add sub-objective','noop'],['chart','Add KPI','noop'],['check','Add task','noop'],['move','Move to focus area…','noop'],'-',['archive','Archive','toast:Archived.','danger']];
CTX.sfa=v=>[['edit','Edit focus area','plfa'],['plus','Add objective','noop'],['eye2','Focus on this area','sbfocus:'+v],'-',['x','Remove from strategy','toast:Removed.','danger']];
Object.assign(ACT,{pobj:v=>{PS.dtab='overview';objDrawer(v)},pdtab:v=>{const[k,id]=v.split('|');PS.dtab=k;objDrawer(id)},plview:v=>{PS.view=v;draw()},plmyl:v=>{PS.myl=v;draw()},plrt:v=>{PS.rtab=v;draw()},plsb:v=>{PS.sb=v;draw()},plstrat:v=>{PS.strat=+v;draw()},
snsel:v=>{const[o,l]=v.split('|');PS.sel=o+l;draw()},sbcol:v=>{PS.collapsed.has(v)?PS.collapsed.delete(v):PS.collapsed.add(v);draw()},sbcollapse:()=>{if(PS.collapsed.size)PS.collapsed.clear();else PLN().fa.forEach(f=>PS.collapsed.add(f.id));draw()},sbfocus:v=>{PS.focus=PS.focus===v?null:v;draw()},
sbz:v=>{PS.zoom=+v===0?1:Math.min(1.5,Math.max(.5,PS.zoom+(+v)*.1));draw()},
plcreate:(v,t)=>{const r=t.getBoundingClientRect();ctxMenu({preventDefault(){},clientX:r.left,clientY:r.bottom},[['target','New objective','plobjnew'],['layers','New focus area','plfa'],['planner','New plan','plnewplan'],['cal','Schedule a review','toast:Review scheduled.'],['projects','Turn strategy into work','pltw']])},
plneeds:(v,t)=>{const r=t.getBoundingClientRect();ctxMenu({preventDefault(){},clientX:r.right-280,clientY:r.bottom},[['alert','Write 5 Days Posts is overdue by 2 days','pobj:f1-0']])},
plfa:()=>dlg({title:'Focus area',body:`<div class="field" style="margin-top:12px"><label>Name</label><input placeholder="e.g. Social growth"></div><div class="field"><label>Description</label><textarea rows="2"></textarea></div><div class="row2"><div class="field"><label>Start</label><input type="date"></div><div class="field"><label>End</label><input type="date"></div></div><div class="field"><label>Colour</label><div class="swatches">${['#2B63F6','#13A592','#7FBF2A','#E8B820','#F07C1A','#EF5235','#7E5BF2','#64748B'].map((c,i)=>`<button class="sw6 ${!i?'on':''}" style="--c:${c}" data-act="pswatch"></button>`).join('')}</div></div><label class="chk"><input type="checkbox"> Save for reuse</label>`,acts:[['Cancel','noop'],['Save','toast:Focus area saved.:ok','primary']]}),
plobjnew:()=>dlg({title:'New objective',body:`<div class="field" style="margin-top:12px"><label>Title</label><input></div><div class="row2"><div class="field"><label>Focus area</label><select>${PLN().fa.map(f=>`<option>${f.n}</option>`).join('')}</select></div><div class="field"><label>Kind</label><select><option>Goal</option><option>Initiative</option></select></div></div><div class="row2"><div class="field"><label>Owner</label><select>${Object.keys(PEOPLE).map(k=>`<option>${PEOPLE[k][0]}</option>`).join('')}</select></div><div class="field"><label>Due</label><input type="date"></div></div>`,acts:[['Cancel','noop'],['Add objective','toast:Objective added.:ok','primary']]}),
plnewplan:()=>dlg({title:'Plan',body:`<div class="field" style="margin-top:12px"><label>Name</label><input value="${PLN().n}"></div><div class="field"><label>Description</label><textarea rows="2">${PLN().desc}</textarea></div><div class="row2"><div class="field"><label>Start</label><input type="date"></div><div class="field"><label>End</label><input type="date"></div></div><div class="field"><label>Start from strategy</label><select><option>None</option><option>${PLN().n}</option></select></div>`,acts:[['Cancel','noop'],['Save','toast:Saved.:ok','primary']]}),
plnewstrat:()=>dlg({title:'New strategy',body:`<div class="field" style="margin-top:12px"><label>Name</label><input placeholder="e.g. Launch strategy"></div><div class="field"><label>Kinds of objective</label><select><option>Goal, Initiative, Sub-objective</option></select></div><div class="field"><label>Focus areas it starts with</label><select><option>None: plans start empty</option></select></div>`,acts:[['Cancel','noop'],['Create strategy','toast:Strategy created.:ok','primary']]}),
pltw:()=>dlg({title:'Turn into work',body:`<p>Create tasks from these objectives. <b>Nothing is created until you confirm.</b></p><div class="field" style="margin-top:12px"><label>Link to project (optional)</label><select><option>No project</option><option>Harry Kaye quiz funnel</option></select></div>${pobjs().slice(0,2).map(o=>`<fieldset class="twf"><legend>${o.n}</legend><input value="Do the first step for ${o.n.toLowerCase()}"><input value="Review progress"></fieldset>`).join('')}<p class="hint">4 tasks will be created.</p>`,acts:[['Cancel','noop'],['Create 4 tasks','toast:4 tasks created. They show in My work.:ok','primary']]}),
plkpi:()=>dlg({title:'Add KPI',body:`<div class="field" style="margin-top:12px"><label>Start from a saved KPI</label><select><option>Followers</option><option>Sign-ups</option></select></div><div class="row2"><div class="field"><label>Target</label><input></div><div class="field"><label>Unit</label><input placeholder="people, $, %"></div></div><div class="field"><label>A good result goes</label><select><option>Up</option><option>Down</option></select></div>`,acts:[['Cancel','noop'],['Add KPI','toast:KPI added.:ok','primary']]}),
plreading:()=>dlg({title:'Record reading',body:`<div class="row2" style="margin-top:12px"><div class="field"><label>Value</label><input></div><div class="field"><label>Date</label><input type="date"></div></div>`,acts:[['Cancel','noop'],['Save','toast:Reading saved.:ok','primary']]})});
KEY.planner=(e,typing)=>{if(!typing&&e.key==='/'){e.preventDefault();$('.pltop input')?.focus()}};
SEARCH.push(()=>pobjs().map(o=>({app:'planner',t:o.n,s:'Objective · '+o.fa.n+' · '+KST[o.st][0],href:'planner/plan/map'})));
